first_max <- function(values) which.max(values)
bellman <- function(environment, values, gamma, state, action) {
  total <- 0
  for (outcome in environment$transitions[[state, action]]) {
    cell <- outcome[[1L]]
    target <- environment$world$state_index[[cell]]
    future <- if (target == 0L) 0 else (gamma * values[[target]]) %/% 100
    total <- total + outcome[[2L]] * (10000 * reward(environment, cell) + future)
  }
  total %/% environment$slip_total
}
action_values <- function(environment, values, gamma, state) vapply(
    seq_len(4L),
    function(action) bellman(environment, values, gamma, state, action),
    0
)
greedy_policy <- function(environment, values, gamma) vapply(
    seq_along(values),
    function(state) first_max(action_values(environment, values, gamma, state)),
    0L
)
value_iteration <- function(environment, gamma, theta) {
  values <- numeric(length(environment$world$states))
  changes <- numeric()
  repeat {
    updated <- vapply(
        seq_along(values),
        function(state) max(action_values(environment, values, gamma, state)),
        0
    )
    change <- max(abs(updated - values))
    changes <- c(changes, change)
    values <- updated
    if (change <= theta) return(list(values = values, changes = changes))
  }
}
in_place_value_iteration <- function(environment, gamma, theta) {
  values <- numeric(length(environment$world$states))
  sweeps <- 0L
  repeat {
    sweeps <- sweeps + 1L
    delta <- 0
    for (state in seq_along(values)) {
      value <- max(action_values(environment, values, gamma, state))
      delta <- max(delta, abs(value - values[[state]]))
      values[[state]] <- value
    }
    if (delta <= theta) return(list(values = values, sweeps = sweeps))
  }
}
evaluate_policy <- function(environment, policy, initial, gamma, theta) {
  values <- initial
  sweeps <- 0L
  repeat {
    sweeps <- sweeps + 1L
    delta <- 0
    for (state in seq_along(policy)) {
      value <- bellman(environment, values, gamma, state, policy[[state]])
      delta <- max(delta, abs(value - values[[state]]))
      values[[state]] <- value
    }
    if (delta <= theta) return(list(values = values, sweeps = sweeps))
  }
}
policy_iteration <- function(environment, gamma, theta) {
  policy <- rep.int(1L, length(environment$world$states))
  values <- numeric(length(policy))
  rounds <- list()
  repeat {
    evaluation <- evaluate_policy(environment, policy, values, gamma, theta)
    values <- evaluation$values
    improved <- greedy_policy(environment, values, gamma)
    changes <- sum(improved != policy)
    rounds[[length(rounds) + 1L]] <- c(evaluation$sweeps, changes, values[[environment$world$start_state]])
    policy <- improved
    if (changes == 0L) return(list(policy = policy, values = values, rounds = rounds))
  }
}

ACTION_LETTERS <- c("N", "E", "S", "W")
ROW_STEPS <- c(-1L, 0L, 1L, 0L)
COLUMN_STEPS <- c(0L, 1L, 0L, -1L)
new_object <- function(...) list2env(list(...), parent = emptyenv())
read_world <- function(path) {
  lines <- readLines(path, warn = FALSE)
  rows <- as.integer(strsplit(lines[[1L]], " ", fixed = TRUE)[[1L]][[2L]])
  cols <- as.integer(strsplit(lines[[2L]], " ", fixed = TRUE)[[1L]][[2L]])
  kinds <- strsplit(paste(lines[seq.int(3L, rows + 2L)], collapse = ""), "", fixed = TRUE)[[1L]]
  wind <- as.integer(strsplit(
      strsplit(lines[[rows + 3L]], " ", fixed = TRUE)[[1L]][[2L]],
      "",
      fixed = TRUE
  )[[1L]])
  rewards <- as.numeric(strsplit(lines[[rows + 4L]], " ", fixed = TRUE)[[1L]][-1L])
  terminals <- which(kinds %in% c("G", "P"))
  states <- which(!(kinds %in% c("#", "G", "P")))
  state_index <- terminal_index <- integer(length(kinds))
  state_index[states] <- seq_along(states)
  terminal_index[terminals] <- seq_along(terminals)
  start <- which(kinds == "S")
  list(rows = rows, cols = cols, kinds = kinds, wind = wind, rewards = rewards,
       states = states, terminals = terminals, state_index = state_index, terminal_index = terminal_index,
       start = start, start_state = state_index[[start]])
}
is_terminal <- function(world, cell) world$terminal_index[[cell]] != 0L
terminal_name <- function(world, cell) if (world$kinds[[cell]] == "G") "goal" else "pit"
move <- function(world, cell, direction) {
  target <- cell + ROW_STEPS[[direction]] * world$cols + COLUMN_STEPS[[direction]]
  if (world$kinds[[target]] == "#") target <- cell
  if (is_terminal(world, target)) return(target)
  for (i in seq_len(world$wind[[(cell - 1L) %% world$cols + 1L]])) {
    above <- target - world$cols
    if (world$kinds[[above]] == "#") break
    target <- above
    if (is_terminal(world, target)) break
  }
  target
}
new_generator <- function(seed) new_object(value = seed)
draw <- function(generator) {
  generator$value <- (48271 * generator$value) %% 2147483647
  generator$value
}
new_environment <- function(world, step_reward, total, floor_slip, ice_slip) {
  n <- length(world$states)
  moves <- matrix(0L, n, 4L)
  transitions <- matrix(vector("list", n * 4L), n, 4L)
  for (state in seq_len(n)) {
    for (direction in seq_len(4L)) moves[state, direction] <- move(world, world$states[[state]], direction)
    slip <- if (world$kinds[[world$states[[state]]]] == "~") ice_slip else floor_slip
    for (action in seq_len(4L)) {
      directions <- c(action, action %% 4L + 1L, (action + 2L) %% 4L + 1L)
      weights <- c(total - 2 * slip, slip, slip)
      outcomes <- list()
      for (i in seq_len(3L)) if (weights[[i]] > 0) outcomes[[length(outcomes) + 1L]] <- c(
          moves[state, directions[[i]]],
          weights[[i]]
      )
      transitions[[state, action]] <- outcomes
    }
  }
  list(world = world, step_reward = step_reward, slip_total = total, floor_slip = floor_slip,
       ice_slip = ice_slip, moves = moves, transitions = transitions)
}
reward <- function(environment, cell) {
  index <- environment$world$terminal_index[[cell]]
  if (index == 0L) environment$step_reward else environment$world$rewards[[index]]
}
environment_step <- function(environment, generator, state, action) {
  sample <- draw(generator) %% environment$slip_total
  slip <- if (environment$world$kinds[[environment$world$states[[state]]]] == "~") environment$ice_slip else environment$floor_slip
  direction <- if (sample < environment$slip_total - 2 * slip) action else if (sample < environment$slip_total - slip) action %% 4L + 1L else (action + 2L) %% 4L + 1L
  cell <- environment$moves[state, direction]
  c(cell, reward(environment, cell))
}

discounted_return <- function(rewards, gamma) {
  value <- 0
  for (reward in rev(rewards)) value <- 10000 * reward + (gamma * value) %/% 100
  value
}
new_return_averages <- function(n) new_object(sums = matrix(0, n, 4L), counts = matrix(0L, n, 4L))
update_averages <- function(averages, learner, history, gamma) {
  seen <- character()
  first_visits <- logical(length(history))
  for (i in seq_along(history)) {
    step <- history[[i]]
    key <- paste(step[[1L]], step[[2L]], sep = ":")
    first_visits[[i]] <- !(key %in% seen)
    seen <- union(seen, key)
  }
  value <- 0
  for (i in rev(seq_along(history))) {
    step <- history[[i]]
    state <- step[[1L]]
    action <- step[[2L]]
    value <- 10000 * step[[3L]] + (gamma * value) %/% 100
    if (first_visits[[i]]) {
      averages$sums[state, action] <- averages$sums[state, action] + value
      averages$counts[state, action] <- averages$counts[state, action] + 1L
      learner$q[state, action] <- averages$sums[state, action] %/% averages$counts[state, action]
    }
  }
}

POLICY_SYMBOLS <- c("^", ">", "v", "<")
integer_text <- function(value) sprintf("%.0f", value)
fixed_text <- function(value) paste0(
    ifelse(value < 0, "-", ""),
    integer_text(abs(value) %/% 10000),
    ".",
    sprintf("%04d", as.integer(abs(value) %% 10000))
)
average_text <- function(total, count) fixed_text((10000 * total) %/% count)
cell_text <- function(world, cell) paste0((cell - 1L) %/% world$cols, ",", (cell - 1L) %% world$cols)
cells_text <- function(world, cells) paste(cell_text(world, cells), collapse = " ")
grid_lines <- function(world, fields, separator) {
  lines <- character()
  for (row in seq_len(world$rows)) {
    cells <- seq.int((row - 1L) * world$cols + 1L, row * world$cols)
    parts <- world$kinds[cells]
    states <- world$state_index[cells]
    parts[states > 0L] <- fields[states[states > 0L]]
    lines <- c(lines, paste(parts, collapse = separator))
  }
  lines
}
value_grid <- function(world, values) grid_lines(world, fixed_text(values), " ")
policy_grid <- function(world, policy) grid_lines(world, POLICY_SYMBOLS[policy], "")
symbol_grid <- function(world, symbols) grid_lines(world, symbols, "")
q_table_rows <- function(world, name, q, visits) {
  lines <- character()
  for (state in seq_along(world$states)) {
    cell <- world$states[[state]]
    for (action in seq_len(4L)) {
      count <- if (is.null(visits)) "-" else integer_text(visits[state, action])
      lines <- c(lines, paste(name, (cell - 1L) %/% world$cols, (cell - 1L) %% world$cols,
                            ACTION_LETTERS[[action]], fixed_text(q[state, action]), count, sep = ","))
    }
  }
  lines
}
join_parts <- function(parts) {
  lines <- character()
  for (part in parts) {
    if (length(lines)) lines <- c(lines, "")
    lines <- c(lines, part)
  }
  lines
}
write_lines <- function(path, lines) writeLines(lines, path, useBytes = TRUE)

choose <- function(generator, row, epsilon) {
  if (draw(generator) %% 1000 < epsilon) as.integer(draw(generator) %% 4) + 1L else first_max(row)
}
td_target <- function(
    reward,
    terminal,
    next_value,
    gamma
) 10000 * reward + if (terminal) 0 else (gamma * next_value) %/% 100
expected_value <- function(row, epsilon) (epsilon * sum(row) + 4 * (1000 - epsilon) * max(row)) %/% 4000
td_update <- function(learner, state, action, target, alpha) {
  learner$q[state, action] <- learner$q[state, action] + (alpha * (target - learner$q[state, action])) %/% 100
}
new_dyna_model <- function(n) new_object(outcomes = matrix(vector("list", n * 4L), n, 4L), pairs = list())
record_model <- function(model, state, action, reward, next_state) {
  if (is.null(model$outcomes[[state, action]])) model$pairs[[length(model$pairs) + 1L]] <- c(state, action)
  model$outcomes[[state, action]] <- c(reward, next_state)
}
plan <- function(model, generator, learner, gamma, alpha, count) {
  for (i in seq_len(count)) {
    pair <- model$pairs[[draw(generator) %% length(model$pairs) + 1L]]
    state <- pair[[1L]]
    action <- pair[[2L]]
    outcome <- model$outcomes[[state, action]]
    next_state <- outcome[[2L]]
    next_value <- if (next_state == 0L) 0 else max(learner$q[next_state, ])
    td_update(learner, state, action, td_target(outcome[[1L]], next_state == 0L, next_value, gamma), alpha)
  }
}
